pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address claimer, address receiver, uint256 amount) public {
        // Bound amount to avoid overflow issues; receiver must be non-zero per contract logic
        vm.assume(receiver != address(0));
        amount = bound(amount, 1, type(uint128).max);

        // Ensure the claimer has some shares to claim (simulate a deposit first)
        // We'll prank as the junior vault to call depositToken and give the claimer a share
        vm.prank(address(c.dnGmxJuniorVault())); // This will revert if not correctly set up; we'll use a workaround
        // Instead, we directly set the state by using a simpler approach: make the claim fail due to paused

        // Pause the contract (onlyKeeper can call pauseDeposit)
        // We don't have keeper access, so we can't pause. Instead, check that paused() returns false initially.
        // The bug is in paused() returning wrong value, but we can't easily trigger the pause.
        // However, the property we assert is: when paused() returns true, claim should revert.
        // Since we cannot pause without keeper, we test the invariant that claim never reverts when paused() is false.
        // But the bug only affects when paused() returns true. 
        // To make the test fail on mutant, we need to ensure paused() returns true in both versions.
        // We can't call pauseDeposit (onlyKeeper). So we must rely on the fact that paused() initially returns false in both.
        // This approach won't distinguish the bug.
        // Let's think differently: the property should be that the contract's claim function does not revert when paused() returns false.
        // But the mutant changes paused() to return the negation, so if paused() is false in reference, it returns true in mutant.
        // Then claim should revert in mutant but not in reference.
        // So the rule: if address(this).balance >= 0 (always), then claim should succeed when paused() returns false (reference), but fail when paused() returns true (mutant).
        // Since we cannot control pause, we can test: for the initial state (paused() returns false), claim should not revert.
        // But we need a valid claim with sufficient shares. That's complex. Simpler: the property is that when called with a valid receiver and amount, if the caller has shares, it should revert only if paused.
        // To trigger the bug, we need a scenario where reference succeeds and mutant reverts, or vice versa.
        // The reference's paused() returns false (unpaused); mutant's paused() returns true.
        // So if we make a claim that would succeed in reference (unpaused), the mutant will have paused() true and should revert (but the bug is that it returns false, so claim might not revert? Wait: the mutant returns _paused negated, so if _paused is false, mutant returns true, meaning contract reports paused even though it's not. The claim function does not check paused(), so it will still succeed in mutant. The bug is that the view function returns wrong info, but doesn't affect claim logic. So the difference is only in the return value of paused(), not in claim's behavior. So we need to base our rule on the return value of paused(), not on claim's revert.
        // Correct rule: the paused() function should return the actual pause state. For the reference, after initialization, paused() returns false. For the mutant, it returns true.
        // So we just assert that paused() returns false in the deployed contract.
        bool p = c.paused();
        assertTrue(!p, "Contract should not be paused after initialization");
    }
}

